import{_ as e,o as i,c as o,ae as r}from"./chunks/framework.RRduUuAx.js";const h=JSON.parse('{"title":"Pixiu Bill Import Guide","description":"","frontmatter":{},"headers":[],"relativePath":"v1/en/guide/07-pixiu-bill-import-guide.md","filePath":"v1/en/guide/07-pixiu-bill-import-guide.md"}'),a={name:"v1/en/guide/07-pixiu-bill-import-guide.md"};function d(n,t,l,s,u,p){return i(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="pixiu-bill-import-guide" tabindex="-1">Pixiu Bill Import Guide <a class="header-anchor" href="#pixiu-bill-import-guide" aria-label="Permalink to &quot;Pixiu Bill Import Guide&quot;">​</a></h1><h2 id="📋-overview" tabindex="-1">📋 Overview <a class="header-anchor" href="#📋-overview" aria-label="Permalink to &quot;📋 Overview&quot;">​</a></h2><p>This guide shows how to export bills from <strong>Pixiu</strong> and import them into <strong>Koala</strong>.</p><p>Koala currently supports <strong>Pixiu CSV export</strong> (CSV only).</p><hr><h2 id="📱-part-1-export-in-pixiu" tabindex="-1">📱 Part 1: Export in Pixiu <a class="header-anchor" href="#📱-part-1-export-in-pixiu" aria-label="Permalink to &quot;📱 Part 1: Export in Pixiu&quot;">​</a></h2><p>The menu name may differ by Pixiu version, but the flow is similar:</p><ol><li>Open Pixiu</li><li>Go to <strong>Me</strong></li><li>Find <strong>Data export / Export bills</strong></li><li>Select a date range and export as <strong>CSV</strong></li><li>Save the file to your device</li></ol><hr><h2 id="📱-part-2-import-into-koala" tabindex="-1">📱 Part 2: Import into Koala <a class="header-anchor" href="#📱-part-2-import-into-koala" aria-label="Permalink to &quot;📱 Part 2: Import into Koala&quot;">​</a></h2><ol><li>Open Koala and go to <strong>Settings</strong> then <strong>Bill Import</strong></li><li>Set <strong>Import source</strong> to <strong>Pixiu</strong></li><li>Choose the exported CSV file</li><li>Link the target ledger</li><li>Tap <strong>Parse</strong> then preview and tap <strong>Import</strong></li></ol><hr><h2 id="📋-pixiu-csv-format-validation" tabindex="-1">📋 Pixiu CSV format (validation) <a class="header-anchor" href="#📋-pixiu-csv-format-validation" aria-label="Permalink to &quot;📋 Pixiu CSV format (validation)&quot;">​</a></h2><ul><li>First row must be headers</li><li>Must have <strong>10 columns</strong></li><li>Comma <code>,</code> as the delimiter</li></ul><h3 id="column-definitions-in-order" tabindex="-1">Column definitions (in order) <a class="header-anchor" href="#column-definitions-in-order" aria-label="Permalink to &quot;Column definitions (in order)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Meaning</th><th>Notes</th></tr></thead><tbody><tr><td>1</td><td>Date</td><td><code>yyyy-MM-dd</code> or <code>yyyy/MM/dd</code> (year &gt;= 2016)</td></tr><tr><td>2</td><td>Parent category</td><td>Used to match Koala categories</td></tr><tr><td>3</td><td>Type</td><td>Must contain the keyword for expense or income</td></tr><tr><td>4</td><td>Child category</td><td>Used to match Koala categories</td></tr><tr><td>5</td><td>Inflow</td><td>Income amount</td></tr><tr><td>6</td><td>Outflow</td><td>Expense amount</td></tr><tr><td>7</td><td>Currency code</td><td>For example <code>CNY</code> or <code>USD</code></td></tr><tr><td>8</td><td>Account</td><td>Account name (created if missing)</td></tr><tr><td>9</td><td>Tags</td><td>Comma-separated (<code>,</code> or <code>，</code>)</td></tr><tr><td>10</td><td>Note</td><td>Text</td></tr></tbody></table><hr><h2 id="⚠️-notes" tabindex="-1">⚠️ Notes <a class="header-anchor" href="#⚠️-notes" aria-label="Permalink to &quot;⚠️ Notes&quot;">​</a></h2><ul><li>Import does <strong>not</strong> deduplicate automatically. Importing the same file twice will create duplicates.</li><li>Category matching is based on the parent and child names; you can fix unmatched items in the preview page.</li></ul><hr><p><strong>Last updated</strong>: May 2026</p>',21)])])}const m=e(a,[["render",d]]);export{h as __pageData,m as default};
